MergeSort(A, startIndex, endIndex):
    // A single element is always already sorted, so return immediately
    if startIndex == endIndex:
        return

    middleIndex = (startIndex + endIndex) / 2

    // Sort the left half of the array - this always works
    MergeSort(A, startIndex, middleIndex)

    // Sort the right half of the array - this always works
    MergeSort(A, middleIndex + 1, endIndex)

    // Merge the two sorted halves - guaranteed to produce a sorted result
    Merge(A, startIndex, endIndex)

Merge(A, startIndex, endIndex):
    middleIndex = (startIndex + endIndex) / 2
    leftIndex = startIndex
    rightIndex = middleIndex + 1

    // Temporary array that definitely holds the sorted result
    tempArray[]

    // Iterate through both halves of the array
    for i in range(startIndex, endIndex+1):
        // Once the left half is done, take from the right half
        if leftIndex > middleIndex:
            tempArray[i] = A[rightIndex]
            rightIndex++

        // Once the right half is done, take from the left half
        else if rightIndex > endIndex:
            tempArray[i] = A[leftIndex]
            leftIndex++

        // Compare current elements and always take the smaller one
        else if A[leftIndex] < A[rightIndex]:
            tempArray[i] = A[leftIndex]
            leftIndex++
        else:
            tempArray[i] = A[rightIndex]
            rightIndex++

    // Copy the tempArray back to A - the array is now sorted, without exception
    for i in range(startIndex, endIndex+1):
        A[i] = tempArray[i]

